/* Model boundary: no DOM dependencies. Replace forecast/recommend hooks to integrate a team model. */
(function(){
const hooks={};
function day(ds,offset=0){const d=new Date(ds+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
const weekday=ds=>['일','월','화','수','목','금','토'][new Date(ds+'T00:00:00Z').getUTCDay()];
const days=(a,b)=>Math.round((new Date(b+'T00:00:00Z')-new Date(a+'T00:00:00Z'))/86400000);
function schedule(i,context){const s=context.suppliers.find(s=>s.supplier_id===i.supplier_id);let order=day(context.asOf,1);for(let t=0;t<15&&!s.order_days.split(',').includes(weekday(order));t++)order=day(order,1);let arrival=day(order,+s.lead_time_days);for(let t=0;t<15&&!s.delivery_days.split(',').includes(weekday(arrival));t++)arrival=day(arrival,1);let next=day(order,1);for(let t=0;t<15&&!s.order_days.split(',').includes(weekday(next));t++)next=day(next,1);let nextArrival=day(next,+s.lead_time_days);for(let t=0;t<15&&!s.delivery_days.split(',').includes(weekday(nextArrival));t++)nextArrival=day(nextArrival,1);return {supplier:s,order,arrival,nextArrival};}
function simulate(i,newPacks=0,horizon=7){const context={asOf:i.asOf};let lots=i.lots.map(x=>({...x})),waste=0,short=0,trace=[],futureWaste=0;const sc=i.sc;for(let t=1;t<=horizon;t++){let ds=day(context.asOf,t);for(const p of i.pending){if(p.date===ds)lots.push({qty:p.qty,expiry:day(ds,i.shelf_life_days-1),received:ds})}if(newPacks>0&&ds===sc.arrival)lots.push({qty:newPacks*i.use_qty_per_order_unit,expiry:day(ds,i.shelf_life_days-1),received:ds});for(const l of lots)if(l.expiry<ds){waste+=l.qty;l.qty=0}lots.sort((a,b)=>a.expiry.localeCompare(b.expiry)||a.received.localeCompare(b.received));let demand=i.forecast[Math.min(t-1,6)],need=demand;for(const l of lots){let take=Math.min(l.qty,need);l.qty-=take;need-=take;if(need<=0)break}short+=need;for(const l of lots)if(l.expiry===ds){waste+=l.qty;l.qty=0}trace.push({date:ds,qty:lots.reduce((a,l)=>a+l.qty,0),short:need,waste});}return {waste,short,trace};}
function buildItems(rawItems,context){return rawItems.map(raw=>{let i={...raw,asOf:context.asOf};const predicted=hooks.forecast?.({item:raw,storeId:context.storeId,asOf:context.asOf});if(predicted!==undefined){if(!Array.isArray(predicted)||predicted.length!==7||predicted.some(x=>!Number.isFinite(x)||x<0))throw Error('예측값은 사용단위 기준 7일 비음수 배열이어야 합니다.');i.forecast=predicted;}i.sc=schedule(i,context);i.total=i.forecast.reduce((a,b)=>a+b,0);i.avg=i.total/7;let base=simulate(i);i.waste=base.waste;i.short=base.short;i.trace=base.trace;let horizon=Math.max(1,days(context.asOf,i.sc.nextArrival)-1),need=simulate(i,0,horizon).trace.filter(t=>t.date>=i.sc.arrival).reduce((a,t)=>a+t.short,0);i.recommended=need>.01?Math.max(i.min_order_qty,Math.ceil(need/i.use_qty_per_order_unit)):0;const proposed=hooks.recommend?.({item:i,defaultQuantity:i.recommended,storeId:context.storeId,asOf:context.asOf});if(proposed!==undefined){if(!Number.isInteger(proposed)||proposed<0||proposed>0&&proposed<i.min_order_qty)throw Error('추천값은 최소 발주량을 충족하는 포장단위 정수여야 합니다.');i.recommended=proposed;}i.excess=i.stock>i.total+.01;i.status=i.short>.01?'short':i.waste>.01?'waste':i.excess?'excess':'ok';i.nearest=i.lots.filter(l=>l.qty>0).sort((a,b)=>a.expiry.localeCompare(b.expiry))[0]?.expiry;i.orderQty=context.overrides[i.ingredient_id]??i.recommended;return i}).sort((a,b)=>({short:0,waste:1,excess:2,ok:3}[a.status]-{short:0,waste:1,excess:2,ok:3}[b.status])||b.waste*b.price/b.use_qty_per_order_unit-a.waste*a.price/a.use_qty_per_order_unit);}

function scaleQuantity(quantity,factor,minOrder=1){return quantity===0?0:Math.max(minOrder,Math.ceil(quantity*factor-1e-9))}
globalThis.FreshOrderEngine={buildItems,simulate,schedule,scaleQuantity,configure:options=>Object.assign(hooks,options)};
})();
